// Verifies a Dodo Payments webhook (Standard Webhooks spec), keeps it once, and updates the
// public totals plus the contributors board. Returns [] to stop the workflow on anything invalid.
// n8n host needs: DODO_WEBHOOK_SECRET (whsec_...) and NODE_FUNCTION_ALLOW_BUILTIN=crypto
const crypto = require('crypto');

const item = $input.first();
const secret = $env.DODO_WEBHOOK_SECRET;
if (!secret) throw new Error('DODO_WEBHOOK_SECRET is not set on the n8n host');

const headers = item.json.headers || {};
const id = headers['webhook-id'];
const timestamp = headers['webhook-timestamp'];
const signatureHeader = headers['webhook-signature'] || '';
if (!id || !timestamp || !signatureHeader) { console.log('rejected: missing webhook headers'); return []; }

// Replay protection: reject anything older than five minutes.
const ageSeconds = Math.floor(Date.now() / 1000) - Number(timestamp);
if (!Number.isFinite(ageSeconds) || Math.abs(ageSeconds) > 300) { console.log(`rejected: bad timestamp (${ageSeconds}s)`); return []; }

// The signature covers the raw bytes: `${id}.${timestamp}.${body}`, HMAC-SHA256, base64.
const rawBody = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
const key = Buffer.from(String(secret).replace(/^whsec_/, ''), 'base64');
const expected = crypto.createHmac('sha256', key).update(`${id}.${timestamp}.${rawBody}`).digest('base64');

// The header is versioned and may carry several space-separated values: "v1,sigA v1,sigB".
const provided = String(signatureHeader).split(' ').map((part) => part.split(',').pop() || '');
const expectedBuf = Buffer.from(expected);
const ok = provided.some((candidate) => {
  const candidateBuf = Buffer.from(candidate);
  return candidateBuf.length === expectedBuf.length && crypto.timingSafeEqual(candidateBuf, expectedBuf);
});
if (!ok) { console.log('rejected: bad signature'); return []; }

const event = JSON.parse(rawBody);
if (event.type !== 'payment.succeeded') { console.log(`ignored: ${event.type}`); return []; }
const data = event.data || {};

// Idempotency on the webhook id (ring buffer of the last 500 in workflow static data).
const store = $getWorkflowStaticData('global');
store.seen = Array.isArray(store.seen) ? store.seen : [];
if (store.seen.includes(id)) { console.log('ignored: duplicate webhook'); return []; }
store.seen.push(id);
if (store.seen.length > 500) store.seen.splice(0, store.seen.length - 500);

// Amounts arrive in the smallest currency unit.
const amount = Math.round((Number(data.total_amount) || 0)) / 100;
const currency = String(data.currency || 'EUR').toUpperCase();
const customer = data.customer || {};
const email = customer.email || '';
const masked = String(email).replace(/^(.).*(@.*)$/, '$1***$2');

// Board name: the metadata field the /pay form sends, else the billing name.
const metadata = data.metadata || {};
const rawName = String(metadata.display_name || customer.name || 'anonymous');
const name = rawName.replace(/\s+/g, ' ').trim().slice(0, 40) || 'anonymous';
const anonymous = /^anonymous$/i.test(name);

// Public totals.
store.raised = Math.round(((Number(store.raised) || 0) + amount) * 100) / 100;
store.sales = (Number(store.sales) || 0) + 1;

// Contributors board: one entry per name, amounts add up, highest first, top 50 kept.
if (!anonymous) {
  store.contributors = Array.isArray(store.contributors) ? store.contributors : [];
  const existing = store.contributors.find((c) => c.name.toLowerCase() === name.toLowerCase());
  if (existing) {
    existing.amount = Math.round((existing.amount + amount) * 100) / 100;
  } else {
    store.contributors.push({ name, amount });
  }
  store.contributors.sort((a, b) => b.amount - a.amount);
  if (store.contributors.length > 50) store.contributors.length = 50;
}

console.log(`accepted: ${id} ${amount} ${currency} from ${masked} as "${name}" — raised now ${store.raised}`);

return [{ json: { paymentId: data.payment_id || id, amount, currency, email, maskedEmail: masked, name, anonymous, created: new Date().toISOString() } }];

